/** Render security UI without retaining credentials in a model or persistent store. */
export function renderSecurityView({profile, confirming, sessionsHTML='', accountHeading, button, field, formError, submit, icon, esc, t}) {
  const heading = profile
    ? accountHeading(t('TETAPAN AKAUN'), `<span class="portal-account-heading-icon" aria-hidden="true">${icon('lock')}</span>${t('Kata Laluan & Keselamatan')}`, t('Lindungi akaun anda dan urus sesi log masuk.'))
    : `<header class="portal-page-heading"><div><p class="card-kicker">${t('TETAPAN AKAUN')}</p><h1 id="portal-title" tabindex="-1"><span class="portal-account-heading-icon" aria-hidden="true">${icon('lock')}</span>${t('Kata Laluan & Keselamatan')}</h1><p>${t('Lindungi akaun yang sedang log masuk.')}</p></div></header>`;
  return `<div class="portal-security-workspace"><div class="portal-room-navigation portal-account-shortcuts">${button(t('Kembali ke kelas'), 'dashboard', {quiet: true, symbol: 'home'})}</div>${heading}
    <div class="portal-security-layout"><section class="portal-panel portal-password-panel" aria-labelledby="portal-change-title"><div class="portal-panel-title"><div><h2 id="portal-change-title">${icon('lock')}${t('Tukar kata laluan')}</h2><p>${t('Sahkan identiti menggunakan kata laluan semasa.')}${profile?.username ? ` <b>@${esc(profile.username)}</b>` : ''}</p></div></div>
    <form data-portal-form="change-password" novalidate>
      <div class="portal-security-fields">
      ${field('portal-security-current', t('Kata laluan semasa'), {name: 'current_password', type: 'password', autocomplete: 'current-password', max: 128, password: true, secretLabel: t('kata laluan semasa'), help: t('Digunakan hanya untuk mengesahkan identiti anda semula.')})}
      ${field('portal-security-new', t('Kata laluan baharu'), {name: 'password', type: 'password', autocomplete: 'new-password', min: 10, max: 128, password: true, secretLabel: t('kata laluan baharu'), help: t('10–128 aksara. Anda boleh tampal atau menggunakan pengurus kata laluan.')})}
      ${field('portal-security-confirm', t('Sahkan kata laluan baharu'), {name: 'password_confirm', type: 'password', autocomplete: 'new-password', min: 10, max: 128, password: true, secretLabel: t('pengesahan kata laluan baharu'), help: t('Masukkan semula kata laluan baharu yang sama.')})}
      </div><div class="portal-security-submit">${submit(t('Simpan kata laluan baharu'))}</div>${formError()}<p class="portal-security-note portal-security-form-note">${t('Gunakan kata laluan baharu apabila diminta log masuk semula.')} ${t('Terlupa kata laluan semasa?')} ${button(t('Dapatkan pautan reset'), 'security-recover', {quiet: true})}</p>
    </form></section><div class="portal-security-session-workspace">${sessionsHTML}<section class="portal-security-global" aria-labelledby="portal-sessions-title"><div><h3 id="portal-sessions-title">${t('Sesi semua peranti')}</h3>
      <p>${t('Log keluar pada telefon, komputer dan pelayar yang menggunakan akaun ini, termasuk peranti ini.')}</p><details class="portal-session-scope"><summary>${t('Tentang pembatalan sesi')}</summary><p class="portal-security-note">${t('Pelayan membatalkan sesi untuk pembaharuan log masuk. Token akses yang sudah dikeluarkan mungkin masih sah sehingga tamat tempoh; peranti lain tidak semestinya terkeluar serta-merta.')}</p></details></div>${button(t('Log keluar semua peranti'), 'request-logout-all', {danger: true})}
      ${confirming ? `<div class="portal-close-confirmation portal-security-confirm" role="group" aria-labelledby="portal-global-title"><div><h3 id="portal-global-title" tabindex="-1">${t('Log keluar semua peranti?')}</h3><p>${t('Anda juga akan keluar pada peranti ini. Simpan kerja anda dahulu. Untuk kembali, log masuk menggunakan kata laluan anda.')}</p></div><div>${button(t('Batal'), 'cancel-logout-all')}${button(t('Ya, log keluar semua'), 'logout-all', {danger: true})}</div></div>` : ''}
    </section></div></div></div>`;
}
